/* Zendure Energy Card v0.3.0 */
(() => {
  "use strict";
  const TAG = "zendure-energy-card";
  const SUFFIX = { grid: "_grid_off_power", solar: "_solar_input_power", soc: "_electric_level", packs: "_pack_num" };
  const num = v => { const n = Number(v); return Number.isFinite(n) ? n : null; };
  const esc = v => String(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
  const watts = v => `${Math.max(0,Math.round(v)).toLocaleString("de-DE")} W`;
  const pct = v => v == null ? "—" : `${Math.max(0,Math.min(100,Math.round(v)))} %`;
  const suffix = (states,s) => Object.entries(states||{}).filter(([id])=>id.startsWith("sensor.")&&id.endsWith(s)).map(([entityId,state])=>({entityId,state}));
  const base = (id,s) => id.slice(0,-s.length);
  function data(states) {
    const g=suffix(states,SUFFIX.grid), p=suffix(states,SUFFIX.solar), l=suffix(states,SUFFIX.soc), b=suffix(states,SUFFIX.packs);
    let grid=0, solar=0;
    g.forEach(x=>{const v=num(x.state?.state);if(v==null)return;if(v>=0)grid+=v;else solar+=Math.abs(v);});
    p.forEach(x=>{const v=num(x.state?.state);if(v!=null&&v>0)solar+=v;});
    const ids=[...new Set(l.map(x=>base(x.entityId,SUFFIX.soc)))];
    const systems=ids.map((id,i)=>{const lv=l.find(x=>base(x.entityId,SUFFIX.soc)===id);const pk=b.find(x=>base(x.entityId,SUFFIX.packs)===id);const pv=pk?num(pk.state?.state):null;return{id,index:i,soc:num(lv?.state?.state),batteries:pv==null?1:Math.max(1,Math.round(pv))};});
    const levels=l.map(x=>num(x.state?.state)).filter(v=>v!=null);
    return {grid,solar,systems,soc:levels.length?levels.reduce((a,v)=>a+v,0)/levels.length: null,batteries:systems.reduce((a,x)=>a+x.batteries,0)};
  }
  class ZendureEnergyCard extends HTMLElement {
    constructor(){super();this.attachShadow({mode:"open"});this._config={};this._hass=null;this._sig="";}
    setConfig(c){if(!c||typeof c!=="object")throw new Error("Invalid Zendure Energy Card configuration");this._config=c;this._sig="";this.render();}
    set hass(h){this._hass=h;this.render();}
    getCardSize(){return 6;}
    getGridOptions(){return{rows:6,columns:6,min_rows:4,min_columns:3};}
    render(){
      if(!this._hass?.states)return;const d=data(this._hass.states),sig=JSON.stringify(d);if(sig===this._sig)return;this._sig=sig;
      const title=this._config.title??"Zendure SolarFlow", soc=d.soc==null?0:Math.max(0,Math.min(100,d.soc));
      this.shadowRoot.innerHTML=`<style>
      :host{display:block;--bg:var(--ha-card-background,var(--card-background-color,#fff));--fg:var(--primary-text-color,#17202a);--muted:var(--secondary-text-color,#69727d);--line:color-mix(in srgb,var(--fg) 12%,transparent);--green:#12d9a1;--yellow:#ffd24a;--purple:#8d72ff;--blue:#50aaff;--shadow:rgba(0,0,0,.22);font-family:Roboto,Arial,sans-serif}ha-card{overflow:hidden;border-radius:22px;background:var(--bg);color:var(--fg);box-shadow:0 6px 24px var(--shadow)}.card{position:relative;min-height:420px;overflow:hidden;background:radial-gradient(ellipse at 50% 65%,color-mix(in srgb,var(--green) 6%,transparent),transparent 48%)}.head{position:absolute;z-index:5;top:14px;left:16px;right:16px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:9px}.metric{padding:9px 11px;border:1px solid var(--line);border-radius:15px;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(10px);box-shadow:0 3px 12px var(--shadow);min-width:0}.metric .v{font-size:clamp(19px,4.6vw,30px);font-weight:800;letter-spacing:-.045em;line-height:1}.metric .l{margin-top:5px;font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.metric.grid .v{color:var(--yellow)}.metric.solar .v{color:var(--green)}.scene{position:absolute;inset:82px 0 54px}.scene svg{width:100%;height:100%;display:block}.bottom{position:absolute;z-index:6;left:16px;right:16px;bottom:11px;display:flex;justify-content:center}.soc{position:absolute;left:0;bottom:0;min-width:145px;padding:8px 12px;border:1px solid var(--line);border-radius:15px;background:color-mix(in srgb,var(--bg) 84%,transparent);backdrop-filter:blur(10px);box-shadow:0 3px 12px var(--shadow)}.soc .v{font-size:23px;font-weight:800;color:var(--green)}.soc .l{font-size:10px;color:var(--muted)}.bar{height:5px;margin-top:7px;border-radius:9px;background:color-mix(in srgb,var(--fg) 12%,transparent);overflow:hidden}.bar i{display:block;width:${soc}%;height:100%;background:var(--green);border-radius:9px;box-shadow:0 0 9px color-mix(in srgb,var(--green) 60%,transparent)}.count{padding:8px 18px;border:1px solid var(--line);border-radius:17px;background:color-mix(in srgb,var(--bg) 84%,transparent);backdrop-filter:blur(10px);box-shadow:0 3px 12px var(--shadow);text-align:center}.count strong{font-size:14px}.count span{display:block;margin-top:2px;color:var(--muted);font-size:10px}.brand{position:absolute;right:18px;bottom:14px;font-size:9px;color:var(--muted);opacity:.65}@media(max-width:500px){.card{min-height:365px}.head{top:9px;left:9px;right:9px;gap:5px}.metric{padding:7px 8px;border-radius:12px}.metric .v{font-size:18px}.metric .l{font-size:8px}.scene{inset:72px 0 50px}.soc{min-width:115px;padding:7px 9px}.soc .v{font-size:20px}.count{padding:7px 11px}.count strong{font-size:11px}.brand{display:none}}
      </style><ha-card><div class="card"><div class="head"><div class="metric grid"><div class="v">${watts(d.grid)}</div><div class="l">Off-Grid-Steckdosenlast</div></div><div class="metric solar"><div class="v">${watts(d.solar)}</div><div class="l">Solarleistung</div></div><div class="metric"><div class="v">${esc(title)}</div><div class="l">Energiemanagement</div></div></div><div class="scene">${this.svg(d)}</div><div class="bottom"><div class="soc"><div class="v">${pct(d.soc)}</div><div class="l">Batterie · Ø SoC</div><div class="bar"><i></i></div></div><div class="count"><strong>${d.systems.length} Speicher · ${d.batteries} Batterie${d.batteries===1?"":"n"}</strong><span>SolarFlow System${d.systems.length===1?"":"e"}</span></div></div><div class="brand">ZENDURE · ENERGY FLOW</div></div></ha-card>`;
    }
    svg(d){
      if(!d.systems.length)return `<div style="height:100%;display:grid;place-items:center;color:var(--muted)">Keine Zendure-Speichersysteme gefunden</div>`;
      const systems=d.systems.slice(0,Math.min(4,Number(this._config.max_systems)||4));const batteries=Math.min(8,Number(this._config.max_batteries)||8,d.batteries);
      const xs=systems.length===1?[360]:systems.map((_,i)=>235+i*250/Math.max(1,systems.length-1));
      const bx=batteries===1?[360]:Array.from({length:batteries},(_,i)=>145+i*430/Math.max(1,batteries-1));
      const defs=`<defs><linearGradient id="r" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3d4854"/><stop offset="1" stop-color="#182028"/></linearGradient><linearGradient id="w" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#69737e"/><stop offset="1" stop-color="#303943"/></linearGradient><linearGradient id="bat"><stop stop-color="#56636f"/><stop offset="1" stop-color="#202a33"/></linearGradient><linearGradient id="win" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#9fd6ff"/><stop offset="1" stop-color="#152a42"/></linearGradient><filter id="sh"><feDropShadow dx="0" dy="4" stdDeviation="4" flood-opacity=".28"/></filter><filter id="gl"><feGaussianBlur stdDeviation="2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>`;
      const panels=Array.from({length:7},(_,i)=>{const x=205+i*53,y=58+(i%2)*3;return`<g transform="skewX(-12)"><rect x="${x}" y="${y}" width="58" height="29" rx="2" fill="#182535" stroke="#718093" filter="url(#sh)"/>${Array.from({length:6},(_,j)=>`<path d="M${x+9+j*9} ${y}v29" stroke="#647487" stroke-width=".5" opacity=".7"/>`).join("")}<path d="M${x} ${y+14.5}h58" stroke="#647487" stroke-width=".5" opacity=".6"/></g>`}).join("");
      const house=`<path d="M90 160L158 101H562L630 160V267H90Z" fill="url(#w)" stroke="#7b8792"/><path d="M58 163L151 42H569L662 163L630 179L559 77H161L90 179Z" fill="url(#r)" stroke="#707c88"/><path d="M113 185H215V257H113Z" fill="url(#win)" stroke="#aab8c5"/><path d="M164 185V257M113 221H215" stroke="#d0e7f7" opacity=".35"/><path d="M486 183H603V257H486Z" fill="url(#win)" stroke="#aab8c5"/><path d="M544 183V257M486 220H603" stroke="#d0e7f7" opacity=".35"/>${panels}`;
      const storage=systems.map((s,i)=>{const x=xs[i],lvl=s.soc==null?0:Math.max(0,Math.min(100,s.soc)),h=30*lvl/100;return`<g filter="url(#sh)"><rect x="${x-31}" y="178" width="62" height="64" rx="7" fill="url(#bat)" stroke="#84909c"/><rect x="${x-23}" y="186" width="46" height="48" rx="4" fill="#303b45"/><rect x="${x-8}" y="193" width="16" height="30" rx="2" fill="#101820" stroke="#84909c"/><rect x="${x-5}" y="${223-h}" width="10" height="${Math.max(1,h)}" rx="1" fill="#12d9a1" filter="url(#gl)"/><circle cx="${x}" cy="230" r="2.5" fill="#12d9a1"/><text x="${x}" y="256" fill="currentColor" font-size="8" font-weight="700" text-anchor="middle">Speicher ${i+1}</text><text x="${x}" y="267" fill="currentColor" opacity=".55" font-size="7" text-anchor="middle">${s.batteries} Batterie${s.batteries===1?"":"n"}</text></g>`}).join("");
      const bat=bx.map((x,i)=>`<g filter="url(#sh)"><rect x="${x-21}" y="239" width="42" height="28" rx="5" fill="#3c4853" stroke="#7c8995"/><rect x="${x-14}" y="246" width="28" height="4" rx="2" fill="#12d9a1"/><rect x="${x-14}" y="254" width="20" height="4" rx="2" fill="#12d9a1" opacity=".55"/><text x="${x}" y="280" fill="currentColor" opacity=".5" font-size="7" text-anchor="middle">B${i+1}</text></g>`).join("");
      const flows=`<path d="M360 88V177" stroke="#ffd24a" stroke-width="3" stroke-linecap="round" filter="url(#gl)"/><path d="M360 242V220" stroke="#12d9a1" stroke-width="3" stroke-linecap="round" filter="url(#gl)"/><path d="M90 215H48" stroke="#50aaff" stroke-width="3" stroke-linecap="round" filter="url(#gl)"/><path d="M630 215H672" stroke="#8d72ff" stroke-width="3" stroke-linecap="round" filter="url(#gl)"/><circle cx="360" cy="88" r="4" fill="#ffd24a"/><circle cx="630" cy="215" r="4" fill="#8d72ff"/>`;
      return `<svg viewBox="0 0 720 300" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(`${d.systems.length} Speichersysteme, ${d.batteries} Batterien`)}">${defs}${house}${flows}${storage}${bat}<g filter="url(#sh)"><rect x="337" y="135" width="46" height="42" rx="5" fill="#d6dbe0" stroke="#687581"/><rect x="347" y="144" width="26" height="20" rx="3" fill="#0e151b"/><circle cx="360" cy="154" r="4" fill="#12d9a1"/><path d="M355 168h10" stroke="#687581" stroke-width="2"/></g></svg>`;
    }
  }
  if(!customElements.get(TAG))customElements.define(TAG,ZendureEnergyCard);
  window.customCards=window.customCards||[];
  if(!window.customCards.some(x=>x.type===TAG))window.customCards.push({type:TAG,name:"Zendure Energy Card",description:"Visualizes Zendure SolarFlow systems, batteries and power flow.",preview:true,documentationURL:"https://github.com/leonsio/zendure-energy-card"});
})();
